import{_ as i,o as n,c as a,a2 as t}from"./chunks/framework.Y8If66rx.js";const u=JSON.parse('{"title":"Specification: mixed column sizing","description":"","frontmatter":{},"headers":[],"relativePath":"reference/column-sizing-spec.md","filePath":"reference/column-sizing-spec.md"}'),o={name:"reference/column-sizing-spec.md"};function l(s,e,r,c,d,p){return n(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="specification-mixed-column-sizing" tabindex="-1">Specification: mixed column sizing <a class="header-anchor" href="#specification-mixed-column-sizing" aria-label="Permalink to &quot;Specification: mixed column sizing&quot;">​</a></h1><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><ul><li>CS-01: Each leaf column supports <code>meta.sizingMode: &quot;pixel&quot; | &quot;percentage&quot;</code>. The default is pixel. Mode is independent of native <code>enableResizing</code>.</li><li>CS-02: Pixel widths use native <code>size</code>, <code>columnSizing</code>, <code>minSize</code>, and <code>maxSize</code>. Resizing an ordinary pixel column changes only its own pixel state.</li><li>CS-03: Percentage columns divide container width after pixel widths are subtracted, proportionally to finite non-negative weights; at least one percentage weight must be positive. The default weight is one.</li><li>CS-04: Percentage drag updates relative weights, never stores those weights as pixel state, and preserves proportional scaling after container resizing.</li><li>CS-05: Minimum and maximum constraints remain pixels for every mode. Redistribute constrained shares. Overflow horizontally at combined minimums; leave space unused when combined maximums prevent filling.</li><li>CS-06: Disabled columns have no handles and cannot be resize partners. Disabled percentage columns still respond to container-space changes.</li><li>CS-07: Percentage transfers use the nearest enabled percentage peer, favoring the following column on ties. Without one, use the nearest enabled pixel column. No partner means no misleading handle.</li><li>CS-08: An all-pixel table uses its last resizable column as flexible fallback. <code>pixelFallback=&quot;widest&quot;</code> instead selects the largest current pixel size, favoring the last on ties. Fixed columns cannot be fallback targets.</li><li>CS-09: When no all-pixel fallback is eligible, keep fixed widths and allow unused space or horizontal overflow. A fallback&#39;s own bounds still apply.</li><li>CS-10: Native <code>columnResizeDirection</code> controls both layout direction and pointer/keyboard deltas. RTL and LTR must grow toward logical inline-end.</li><li>CS-11: Respect native table/column resize permission and native commit mode. Default <code>onEnd</code> previews without committing; release commits both state maps. <code>onChange</code> commits during movement. Keyboard actions commit immediately.</li><li>CS-12: Expose controlled <code>columnWeights</code> and <code>onColumnWeightsChange</code>; require the callback when weights are controlled. Use native controlled pixel state.</li><li>CS-13: Invalid modes, weights, constraints, or container widths fail explicitly. Do not mask errors with success-shaped defaults.</li><li>CS-14: Align header/body widths, preserve sorting, stable row identity, virtualization, Gantt observations, and application-independent packaging.</li><li>CS-15: Standalone and application table implementations must remain equivalent.</li></ul><h2 id="input-and-accessibility" tabindex="-1">Input and accessibility <a class="header-anchor" href="#input-and-accessibility" aria-label="Permalink to &quot;Input and accessibility&quot;">​</a></h2><ul><li>CS-16: Focusable vertical separators expose a single-column accessible name and actual rendered width through <code>aria-valuenow</code>.</li><li>CS-17: Arrow keys move by 2px, Shift+Arrow by 10px. Home requests the lower bound; End requests the viewport-limited upper bound. Apply both partner constraints. Do not produce infinite CSS widths.</li><li>CS-18: Capture the primary pointer. Finish on release, cancel, or capture loss. Cancel the snapshot on container resizing.</li><li>CS-19: Cancellation discards uncommitted <code>onEnd</code> previews; already committed <code>onChange</code> values remain.</li></ul><h2 id="acceptance-examples" tabindex="-1">Acceptance examples <a class="header-anchor" href="#acceptance-examples" aria-label="Permalink to &quot;Acceptance examples&quot;">​</a></h2><ol><li>In a 1000px container, two 100px pixel columns plus weights <code>1:3</code> render <code>100, 100, 200, 600</code>. At 1400px, render <code>100, 100, 300, 900</code>.</li><li>With one 100px pixel and two equal percentage columns, render <code>100, 450, 450</code>. Growing the first percentage column by 90px produces <code>100, 540, 360</code>; at 1600px, render <code>100, 900, 600</code>.</li><li>Growing an enabled pixel column does not resize an adjacent ordinary pixel column. Percentage space or the all-pixel fallback absorbs the difference.</li><li>A disabled pixel neighbor never changes during direct percentage resizing; the nearest enabled partner is used instead.</li><li>If all pixel columns are disabled, growing the container does not grow any column. No resize handles exist.</li><li>If only one percentage column exists and no enabled pixel partner exists, it still scales with its container, but has no handle.</li><li>Dragging RTL left by 40px has the same logical effect as dragging LTR right by 40px. RTL ArrowLeft and LTR ArrowRight have matching effects.</li><li>A 160px minimum Gantt column remains at least 160px; chart/header widths remain aligned after resizing and sorting.</li><li><code>onEnd</code> produces no sizing callback during preview and commits on release. <code>onChange</code> produces callbacks during movement.</li></ol><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>Run <code>npm test</code>, <code>npm run lint</code>, <code>npm run build</code>, and <code>npm run docs:build</code> in the standalone package. Run application table/schedule typechecks and the design-system component tests. Validate real pointer/keyboard interaction, container resizing, RTL, and Gantt alignment in a browser.</p><h2 id="non-goals" tabindex="-1">Non-goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-goals&quot;">​</a></h2><p>No percentage-of-entire-table mode, automatic persistence, new dependencies, column pinning, grouped-column resize interaction, or change to Gantt internals. Native size getters remain pixel-state getters rather than renderer layout measurements. The existing public <code>resizeColumnPair</code> utility remains compatible.</p>',11)])])}const h=i(o,[["render",l]]);export{u as __pageData,h as default};
